using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.Configuration;

namespace InformationWeb.Controls
{
    public partial class MainMenu : System.Web.UI.UserControl
    {

        protected string GetProfileUrl = "/";
        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                ShowMenu();


                SetControlsVisibility(false,
                    liSummaryTestScheduleOfTeacherExam,
                    liTeacherWorkList,
                    liSummaryScheduleOfTeacherExam,
                    liEthicStudent,
                    liListEthicStudent,
                    liSummaryEthicMark,
                    //liSubjectMarkDetail,
                    mnuRegisterClassSubject,// đăng ký học phần
                    liReExam,//đăng ký thi lại


                    liSummary_2,
                    liSummary,

                    liPollManager,

                    liExamMarkEdit
                );
            }
        }
        /// <summary>
        /// Đặt trạng thái ẩn/hiện cho nhiều control cùng lúc.
        /// </summary>
        /// <param name="isVisible">True để hiện, False để ẩn</param>
        /// <param name="controls">Danh sách các control cần xử lý</param>
        private void SetControlsVisibility(bool isVisible, params Control[] controls)
        {
            foreach (Control c in controls)
            {
                if (c != null)
                {
                    c.Visible = isVisible;
                }
            }
        }
        public void ShowMenu()
        {
            if (WebGlobal.StudentID > 0)
            {
                ShowMenuForStudent();
                GetProfileUrl = "/ho-so-hs.html";
            }
            else
            {
                ShowMenuForUser();
                GetProfileUrl = "/ho-so-gv.html";
            }
        }

        public void ShowMenuForUser()
        {
            DCore.SessionUser objUser = Session[DCore.Globals.USER] as DCore.SessionUser;
            bool bolHaveLogin = objUser != null;


            bool bolAdmin = (objUser != null && objUser.UserName.ToLower() == "administrator") || (objUser != null && objUser.DepartmentID == 63);
            bool bolTuyenSinhOnline = WebGlobal.HasPermission("WEB_StudentCollection_Manager");
            bool bolRequestSchedule_View = WebGlobal.HasPermission("SIM_RequestSchedule_View");

            liSummaryScheduleOfTeacher.Visible = liSummaryScheduleOfTeacherExam.Visible = liSummaryTestScheduleOfTeacherExam.Visible = true; //Lịch GV -  lịch coi thi chấm thi
            liSummaryScheduleOfRoom.Visible = true; // Lịch Phòng
            titleGD.Visible = titleQL.Visible = true;
            liSubjectMarkEdit.Visible = liScheduleChecking.Visible = liRequestSchedule.Visible = liTeacherWorkList.Visible = liTeachingSchedule.Visible = objUser != null;
            liSummaryEthicMark.Visible = objUser != null && WebGlobal.HasPermission("SIM_SummaryEthicMark_View");

            // nhóm menu Tổng hợp
            bool bolSubjectMarkDetail = WebGlobal.HasPermission("frmWebSubjectMarkDetail_View");
            bool bolChiTietCongNo = WebGlobal.HasPermission("frmChiTietCongNoHocSinh_View");
            bool bolSessionCheckingSummary = WebGlobal.HasPermission("WEB_SessionCheckingSummary"); // tra cứu điểm danh ca trên web
            bool bolStudentList = WebGlobal.HasPermission("frmWebStudentList_View"); // ds lớp 

            bool bolScheduleCheckingSummary_View = WebGlobal.HasPermission("SIM_ScheduleCheckingSummary_View");  // tổng hợp sổ lên lớp
            bool bolTeachingScheduleSummary_View = WebGlobal.HasPermission("SIM_TeachingScheduleSummary_View");  // tổng hợp sổ kế hoạch giảng dạy

            //bool bolPortfo_View = bolAdmin || WebGlobal.HasPermission("CRM_Portfo_View"); // quản lý hồ sơ năng lực HSSV
            bool bolSupport_View = bolAdmin || WebGlobal.HasPermission("CRM_Support_View"); // quản lý nội dung yc
            bool bolSendInfo_View = bolAdmin || WebGlobal.HasPermission("CRM_SendInfo_View"); // quản lý nội dung thông báo

            bool bolSimpleStudentList = bolHaveLogin; // login rùi là dc bolAdmin || WebGlobal.HasPermission("frmWebSimpleStudentList_View"); // ds sv đơn giản cho nhiều user xài hơn 
            liSubjectMarkEdit.Visible = liExamMarkEdit.Visible = liScheduleChecking.Visible = liRequestSchedule.Visible = bolHaveLogin;

            liSubjectMarkDetail.Visible = bolSubjectMarkDetail;
            liCongNo.Visible = bolSubjectMarkDetail;

            liChiTietCongNo.Visible = bolChiTietCongNo;
            liSessionCheckingSummary.Visible = bolSessionCheckingSummary;
            liEthicStudent.Visible = liStudentList.Visible = bolStudentList;

            liScheduleCheckingSummary.Visible = bolScheduleCheckingSummary_View; // tổng hợp sổ lên lớp
            liTeachingScheduleSummary.Visible = bolTeachingScheduleSummary_View; // tổng hợp kế hoạch giảng dạy (lịch trình)

            liStudentCollectionEdit.Visible = objUser == null;


            //liPortfoCMS.Visible = bolPortfo_View;
            liSupportCMS.Visible = bolSupport_View;
            liSendInfoCMS.Visible = bolSendInfo_View;


            liSummary_2.Visible = liSummary.Visible = bolSubjectMarkDetail || bolChiTietCongNo || bolSessionCheckingSummary || bolStudentList || bolScheduleCheckingSummary_View || bolTeachingScheduleSummary_View
                //|| bolPortfo_View || bolSupport_View
                       || bolSendInfo_View;


            liChiTietCongNo.Visible = bolChiTietCongNo;
            bool bolDebtSubjectSummary_View = bolAdmin || WebGlobal.HasPermission("frmDebtSubjectSummary_View");   // tra cứu nợ môn trên web  
            liDebtSubjectSummary.Visible = bolDebtSubjectSummary_View; // tra cứu nợ môn
            liHome.Visible = liContact.Visible = !liUser.Visible;
            //liPollSummary.Visible = liPoll.Visible = false;


            //liAttendFullList_Student.Visible = false; // sv tra cứu chấm công
            liAttendFullList_Teacher.Visible = false; // tra cứu chấm giờ


            // mô đun khảo sát
            bool bolCompany_View = WebGlobal.HasPermission("GEN_Company_View");  // danh mục doanh nghiệp
            bool bolPollPlan_View = WebGlobal.HasPermission("POL_Plan_View");  // kế hoạch khảo át


            bool bolListEthic_View = WebGlobal.HasPermission("POL_Plan_Ethic_View");  // kế hoạch rèn luyện
            liListEthicStudent.Visible = bolListEthic_View;


            liCompany.Visible = bolCompany_View;
            liPollPlan.Visible = bolPollPlan_View;
            liPollManager.Visible = bolCompany_View || bolPollPlan_View;

            // mô đun khảo sát
            //  bool bolCompany_View = WebGlobal.HasPermission("GEN_Company_View");  // danh mục doanh nghiệp
            //   bool bolPollPlan_View = WebGlobal.HasPermission("POL_Plan_View");  // kế hoạch khảo át

            liCompany.Visible = bolCompany_View;
            liPollPlan.Visible = bolPollPlan_View;
            liPollManager.Visible = bolCompany_View || bolPollPlan_View;


            // nhóm menu hệ thóng            
            liRequestScheduleForCMS.Visible = bolRequestSchedule_View; // duyệt đổi lịch            
            liLearningLevel.Visible = liTrainingLevel.Visible = liSpecialBranch.Visible = liStudentCollection.Visible = bolAdmin || bolTuyenSinhOnline;
            liLocationContent.Visible = bolAdmin; // hệ thống chỉ do admin hiệu chỉnh
            liSystem.Visible = bolAdmin || bolTuyenSinhOnline || bolRequestSchedule_View;


            liHome.Visible = liContact.Visible = !liSummary.Visible && !liSystem.Visible; // menu home và contract ẩn bớt khi là admin vì quá nhiều menu

            // mnuReceipt.Visible = false;

            liStudentGraduationResult.Visible = liStudentListSearch.Visible = true; //tra cứu sinh viên
            liStudentList.Visible = true; // trùng gốc: Danh sách lớp
            liUser.Visible = liActionLog.Visible = (objUser != null && objUser.UserName.ToLower() == "administrator");
            udpMenu.Update();
        }

        /// <summary>
        /// Show menu theo sinh viên đăng nhập
        /// </summary>
        public void ShowMenuForStudent()
        {
            DCore.SessionUser objUser = Session[DCore.Globals.USER] as DCore.SessionUser;

            //liPoll.Visible = objUser!=null;
            titleHT.Visible = liSanction.Visible = liReward.Visible = liReExam.Visible = liChuongTrinhDaoTao.Visible = true;
            liSubjectMarkOfStudent.Visible = true;
            mnuRegisterClassSubject.Visible = true; // sinh viên có đăng ký học phần (khi còn đang học mới được)

            liStudentCollection.Visible = liUser.Visible = liActionLog.Visible = false;
            //liPollSummary.Visible = false;
            liSubjectMarkEdit.Visible = false;
            liScheduleChecking.Visible = false;
            liTeachingSchedule.Visible = false;

            liSummaryEthicMark.Visible = false;
            liTeacherWorkList.Visible = false;
            liRequestSchedule.Visible = false;

            liChiTietCongNo.Visible = false;
            liSessionCheckingSummary.Visible = false;
            liEthicStudent.Visible = liStudentList.Visible = false;
            liSummary.Visible = false;
            liListEthicStudent.Visible = liStudentCollectionEdit.Visible = false;

            liHome.Visible = liContact.Visible = true;

            mnuReceipt.Visible = true;
            //liAttendFullList_Student.Visible = objUser != null; // sv tra cứu chấm công
            liAttendFullList_Teacher.Visible = false; // tra cứu chấm giờ

            // mnuReceipt.Visible = WebGlobal.User != null && WebGlobal.User.UserName.ToUpper().Contains("TEST"); // đóng học phí khi là sv và đang là chế độ test
            liStudentGraduationResult.Visible = liStudentListSearch.Visible = false;
            udpMenu.Update();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.Configuration;

namespace InformationWeb.Controls
{
    public partial class MainMenu : System.Web.UI.UserControl
    {
        protected string GetProfileUrl = "/";

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                ShowMenu();
            }
        }

        public void ShowMenu()
        {
            if (WebGlobal.StudentID > 0)
            {
                ShowMenuForStudent();
                GetProfileUrl = "/ho-so-hs.html";
            }
            else
            {
                ShowMenuForUser();
                GetProfileUrl = "/ho-so-gv.html";
            }
            liContact.Visible = false; // tạm không cần 
        }

        public void ShowMenuForUser()
        {
            DCore.SessionUser objUser = Session[DCore.Globals.USER] as DCore.SessionUser;
            bool bolAdmin = (objUser != null && objUser.UserName.ToLower() == "administrator") || (objUser != null && objUser.DepartmentID == 63);

            liSystem.Visible = liLocationContent.Visible = bolAdmin;
            liLearningLevel.Visible = liTrainingLevel.Visible = liSpecialBranch.Visible = liStudentCollection.Visible = bolAdmin;
            liUser.Visible = liActionLog.Visible = (objUser != null && objUser.UserName.ToLower() == "administrator");//chỉ admin xem thôi
            liSubjectMarkEdit.Visible = liScheduleChecking.Visible = objUser != null;

            liHome.Visible = liContact.Visible = !liUser.Visible;
            //liPollSummary.Visible = liPoll.Visible = false;
            mnuReceipt.Visible = false;

            udpMenu.Update();
        }

        /// <summary>
        /// Show menu theo sinh viên đăng nhập
        /// </summary>
        public void ShowMenuForStudent()
        {
            DCore.SessionUser objUser = Session[DCore.Globals.USER] as DCore.SessionUser;

            //liPoll.Visible = objUser!=null;

            liStudentCollection.Visible = liUser.Visible = liActionLog.Visible = false;
            //liPollSummary.Visible = false;
            liSubjectMarkEdit.Visible = false;
            liScheduleChecking.Visible = false;

            liHome.Visible = liContact.Visible = !liUser.Visible;

            mnuReceipt.Visible = true; // đã golive WebGlobal.User.UserName.ToUpper().Contains("TEST"); // đóng học phí khi là sv và đang là chế độ test
            udpMenu.Update();
        }
    }
}

